<?php
declare(strict_types=1);
namespace App\Application\Study\Service;
use App\Application\Study\DTO\Request\CreateDirectedStudyPlanRequestDto;use App\Application\Study\DTO\Response\DirectedStudyPlanResponseDto;use App\Application\Study\Mapper\DirectedStudyPlanResponseMapper;use App\Application\Study\Port\TransactionManagerInterface;use App\Domain\Catalog\Repository\PositionRepositoryInterface;use App\Domain\Study\Entity\DirectedStudyPlan;use App\Domain\Study\Repository\DirectedStudyPlanRepositoryInterface;
final class CreateDirectedStudyPlanService { public function __construct(private readonly DirectedStudyPlanRepositoryInterface $plans,private readonly PositionRepositoryInterface $positions,private readonly DirectedStudyPlanResponseMapper $mapper,private readonly TransactionManagerInterface $transactions){} public function create(CreateDirectedStudyPlanRequestDto $request):DirectedStudyPlanResponseDto {if(!$this->positions->existsForExam($request->positionId,$request->examId))throw new \InvalidArgumentException('O cargo deve pertencer ao concurso escolhido.');return $this->transactions->transactional(function()use($request){foreach($this->plans->listForUser($request->userId) as $existing)if($existing->examId===$request->examId&&$existing->positionId===$request->positionId)return $this->mapper->toResponse($existing);$plan=DirectedStudyPlan::create($request->userId,$request->examId,$request->positionId,$request->name,new \DateTimeImmutable('now'));$this->plans->save($plan);return $this->mapper->toResponse($plan);});} }
